import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useI18n } from '../../i18n/I18nProvider'
import { apiDelete, apiGet, apiPost } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { ImageGenDialog, type ImageGenSubmit } from '../../components/ImageGenDialog'
import { snapResolution } from '../../lib/imageSize'
import { IMAGE_TYPES, type GalleryResponse, type Location, type Room } from './worldTypes'
import { ImageSetDialog } from './ImageSetDialog'

// ── Gallery — list, type-change, night-variant, delete, enlarge. ───────────

interface GalleryCardProps {
  filename: string
  url: string
  type: string
  meta: { backend?: string; model?: string; loras?: string[] }
  isBusy: boolean
  mapUsage: number
  /** Multi-select mode: the thumb toggles selection instead of zooming. */
  selectMode?: boolean
  isSelected?: boolean
  onToggleSelect?: (image: string) => void
  onZoom: (url: string) => void
  onSetType: (image: string, type: string) => void
  onGenerateNight: (image: string) => void
  onRegen: (target: { filename: string; type: string }) => void
  onMove: (image: string) => void
  onRemove: (image: string) => void
  /** Two-step delete: the first click arms THIS tile, the second deletes. */
  removeArmed?: boolean
  /** Turn a building image into the location's 3D model (building tiles only). */
  onGenerateModel?: (image: string) => void
}

const GalleryCard = memo(function GalleryCard({
  filename,
  url,
  type,
  meta,
  isBusy,
  mapUsage,
  selectMode,
  isSelected,
  onToggleSelect,
  onZoom,
  onSetType,
  onGenerateNight,
  onRegen,
  onMove,
  onRemove,
  removeArmed,
  onGenerateModel,
}: GalleryCardProps) {
  const { t } = useI18n()
  return (
    <div className="ga-gallery-card"
      style={selectMode && isSelected
        ? { outline: '2px solid #1f6feb', borderRadius: 6 } : undefined}>
      <button
        type="button"
        className="ga-gallery-thumb"
        onClick={() => (selectMode ? onToggleSelect?.(filename) : onZoom(url))}
        title={selectMode ? t('Toggle selection') : t('Click to enlarge')}
        style={{ position: 'relative' }}
      >
        {selectMode ? (
          <span style={{
            position: 'absolute', top: 6, left: 6, zIndex: 2,
            width: 22, height: 22, borderRadius: 4, textAlign: 'center',
            lineHeight: '22px', fontSize: 14, fontWeight: 700,
            background: isSelected ? '#1f6feb' : 'rgba(0,0,0,0.55)',
            color: '#fff', border: '1px solid rgba(255,255,255,0.6)',
          }}>{isSelected ? '✓' : ''}</span>
        ) : null}
        <img src={url} alt={filename} />
        {type === 'map_2d' || type === 'map_3x3' ? (
          <span
            className="ga-gallery-usage"
            title={t('How many map cells currently use this image')}
          >
            {mapUsage}
          </span>
        ) : null}
      </button>
      <div className="ga-gallery-card-body">
        <div className="ga-gallery-meta">
          {meta.model ? (
            <div>
              <strong>{t('Model')}</strong> {meta.model}
            </div>
          ) : null}
          {meta.loras && meta.loras.length > 0 ? (
            <div>
              <strong>{t('LoRAs')}</strong> {meta.loras.join(', ')}
            </div>
          ) : null}
          {meta.backend ? (
            <div>
              <strong>{t('Provider')}</strong> {meta.backend}
            </div>
          ) : null}
        </div>
        <div className="ga-gallery-actions">
          <select
            className="ga-input ga-gallery-type-select"
            value={type}
            disabled={isBusy}
            onChange={(e) => onSetType(filename, e.target.value)}
            title={t('Image type')}
          >
            <option value="">— {t('type')} —</option>
            {IMAGE_TYPES.filter((x) => x !== '').map((tp) => (
              <option key={tp} value={tp}>
                {tp}
              </option>
            ))}
          </select>
          {type !== 'building' && type !== 'map_3x3' ? (
            <button
              className="ga-btn ga-btn-sm"
              disabled={isBusy}
              onClick={() => onGenerateNight(filename)}
              title={t('Generate a night variant from this image')}
            >
              🌙
            </button>
          ) : null}
          <button
            className="ga-btn ga-btn-sm"
            disabled={isBusy}
            onClick={() => onRegen({ filename, type })}
            title={t('Adjust this image via a reference-capable backend + prompt (saved as a new image)')}
          >
            ♻
          </button>
          <button
            className="ga-btn ga-btn-sm"
            disabled={isBusy}
            onClick={() => onMove(filename)}
            title={t('Move this image to another location')}
          >
            ⇄
          </button>
          {type === 'building' && onGenerateModel ? (
            <button
              className="ga-btn ga-btn-sm"
              disabled={isBusy}
              onClick={() => onGenerateModel(filename)}
              title={t('Generate the 3D building model from this image')}
            >
              🧊
            </button>
          ) : null}
          <button
            className="ga-btn ga-btn-sm ga-btn-danger"
            disabled={isBusy}
            onClick={() => onRemove(filename)}
            title={removeArmed ? t('Click again to delete this image') : t('Delete image')}
          >
            {removeArmed ? t('Sure?') : '×'}
          </button>
        </div>
      </div>
    </div>
  )
})

export function LocationGallery({
  locationId,
  location,
  room,
  roomFilter,
  allLocations,
  placements,
  mode,
  onGenerateModel,
}: {
  locationId: string
  location: Location
  room: Room | null
  /** When set, only images assigned to this room are shown. */
  roomFilter?: string
  /** All places (for the "move image to another location" picker). */
  allLocations: Location[]
  /** Unfiltered list incl. clone placements (for the map-usage counter). */
  placements: Location[]
  /** Which world the gallery serves: '2d' shows everything except building
   *  images (day/night/map icons), '3d' shows only the building images that
   *  feed the 3D model. Follows the location editor's tab split. */
  mode: '2d' | '3d'
  /** Turn a building-type image into a 3D model (🧊 per tile): the location's
   *  building model (3D tab) or — with roomFilter — the room's model. The
   *  caller owns the model panel + backend picker. */
  onGenerateModel?: (image: string) => void
}) {
  const { t } = useI18n()
  const { toast } = useToast()
  const [data, setData] = useState<GalleryResponse | null>(null)
  const [zoom, setZoom] = useState<string | null>(null)
  const [busy, setBusy] = useState<string | null>(null)
  const [dialogType, setDialogType] = useState<'day' | 'night' | 'map_2d' | 'map_3x3' | 'building' | null>(null)
  const [imageSetOpen, setImageSetOpen] = useState(false)
  // "Regenerate" target: recreate an existing map image using it as a reference.
  const [regenTarget, setRegenTarget] = useState<{ filename: string; type: string } | null>(null)
  // "Move image": the open image + the chosen target location.
  const [moveImage, setMoveImage] = useState<string | null>(null)
  const [moveTarget, setMoveTarget] = useState('')

  const reload = useCallback(async () => {
    try {
      const d = await apiGet<GalleryResponse>(
        `/world/locations/${encodeURIComponent(locationId)}/gallery`,
      )
      setData({
        images: d.images || [],
        image_rooms: d.image_rooms || {},
        image_types: d.image_types || {},
        image_metas: d.image_metas || {},
      })
    } catch {
      setData({ images: [] })
    }
  }, [locationId])

  useEffect(() => {
    reload()
  }, [reload])

  // The 3D building model itself (status/viewer/placement) lives in
  // BuildingModelPanel — this gallery only surfaces the 🧊 per building tile
  // via onGenerateModel (3D mode).

  // Move an image to another location (file + prompt/type/meta).
  const submitMove = useCallback(async () => {
    if (!moveImage || !moveTarget) return
    try {
      await apiPost(
        `/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(moveImage)}/move`,
        { target: moveTarget },
      )
      toast(t('Image moved'))
      setMoveImage(null)
      setMoveTarget('')
      await reload()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [moveImage, moveTarget, locationId, reload, t, toast])

  const types = data?.image_types || {}
  const metas = data?.image_metas || {}

  // How often each map image is currently used on the map: placed cells
  // whose gallery owner is this location (clones share the template gallery) and
  // that picked exactly this file as the 2D tile — or as the 3x3 patch
  // anchored there. File -> count.
  const mapUsage = useMemo(() => {
    const m: Record<string, number> = {}
    for (const l of placements) {
      if (l.grid_x == null || l.grid_y == null || l.grid_x < 0 || l.grid_y < 0) continue
      if (((l.template_location_id || '').trim() || l.id) !== locationId) continue
      const f = (l.map_image_2d || '').trim()
      if (f) m[f] = (m[f] || 0) + 1
      const p = (l.map_patch_2d || '').trim()
      if (p) m[p] = (m[p] || 0) + 1
    }
    return m
  }, [placements, locationId])

  // Filter to the selected room (if provided): keep images explicitly
  // assigned to it; images without a room assignment fall back to the
  // location level and stay visible at the location detail. On top of that
  // the mode splits the 2D world (everything except building images) from
  // the 3D world (only the building images that feed the model).
  const images = useMemo(() => {
    const all = data?.images || []
    const rms = data?.image_rooms || {}
    const tps = data?.image_types || {}
    const byRoom = roomFilter
      ? all.filter((f) => (rms[f] || '') === roomFilter)
      : all.filter((f) => !rms[f] || rms[f] === '')
    if (mode === '3d') return byRoom.filter((f) => (tps[f] || '') === 'building')
    // A room view shows ALL its images incl. its building-type model source
    // (the 🧊 lives there); the location-level 2D tab excludes building
    // images — those belong to the 3D tab.
    if (roomFilter) return byRoom
    return byRoom.filter((f) => (tps[f] || '') !== 'building')
  }, [data, roomFilter, mode])

  const setType = useCallback(
    async (image: string, type: string) => {
      setBusy(image)
      try {
        await apiPost(
          `/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(image)}/type`,
          { type },
        )
        await reload()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      } finally {
        setBusy(null)
      }
    },
    [locationId, reload, t, toast],
  )

  const generateNight = useCallback(
    async (image: string) => {
      setBusy(image)
      try {
        await apiPost(
          `/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(image)}/time-variant`,
          { target_type: 'night' },
        )
        toast(t('Night variant queued'))
        await reload()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      } finally {
        setBusy(null)
      }
    },
    [locationId, reload, t, toast],
  )

  // Image shape from the floor plan: the room-model source feeds img2mesh, so
  // a 2 × 5 m room rendered at 1024² comes back as a square box. User finding
  // 2026-07-26: the generator handles LANDSCAPE canvases better for this use
  // case — the LONG side always goes to the WIDTH, whatever the rectangle's
  // orientation on the plan (the mesh takes its true footprint from the image
  // content; the plan yaw orients it later). Only a prefill; the admin
  // overrides it in the dialog. Rooms without a rectangle keep the default.
  const roomResolution = useMemo(() => {
    const w = Number(room?.layout?.w) || 0
    const d = Number(room?.layout?.d) || 0
    if (!(w > 0) || !(d > 0)) return null
    const LONG = 1024
    const ratio = Math.min(w, d) / Math.max(w, d)
    return { width: LONG, height: snapResolution(LONG * ratio) }
  }, [room?.layout?.w, room?.layout?.d])

  // Submit handler the dialog calls on Generate. Truly fire-and-forget —
  // the function returns immediately so ImageGenDialog can close right
  // away. The POST + reload run on a detached promise. Errors land in
  // the toast bus, not on the dialog (which is already gone).
  const submitGenerate = useCallback(
    async (payload: ImageGenSubmit) => {
      if (!dialogType) return
      const body: Record<string, unknown> = {
        prompt_type: dialogType,
        prompt: payload.prompt,
      }
      // Room context: assign the image to the room — including 'building'
      // (the room's model-source image). Map types have no room dimension.
      if (roomFilter && dialogType !== 'map_2d' && dialogType !== 'map_3x3') body.room_id = roomFilter
      if (payload.backend) body.backend = payload.backend
      if (payload.loras) body.loras = payload.loras
      // The dialog already has the map-icon suffix in the prompt → don't duplicate it server-side.
      if (payload.prompt_settings_applied) body.settings_applied = true
      // Negative from the dialog (room-model renders): carries the items the
      // composer's negation guard moved out of the subject — without it the
      // server would fall back to the bare use-case negative and lose them.
      if (payload.negative_prompt) body.negative_prompt = payload.negative_prompt
      // Provenance of the shown prompt — the server logs it with the render.
      if (payload.llm_composed) {
        body.llm_composed = true
        body.cache_hit = !!payload.cache_hit
      }
      // Output size (empty fields = the server's use-case default).
      if (payload.width) body.width = payload.width
      if (payload.height) body.height = payload.height

      // Detached: do NOT await. handleSubmit will see a resolved Promise
      // immediately and trigger onClose() in the next microtask.
      void apiPost(
        `/world/locations/${encodeURIComponent(locationId)}/gallery`,
        body,
      )
        // No auto-refresh: the periodic reloads are disruptive when editing
        // something else in parallel. The new image appears on the next gallery reload.
        .then(() => toast(t('Image queued')))
        .catch((e) => {
          toast(t('Error') + ': ' + (e as Error).message, 'error')
        })
    },
    [dialogType, locationId, roomFilter, t, toast],
  )

  // Regenerate an existing map image — using itself as the reference.
  // Always lands as a NEW gallery image (selectable per cell).
  const submitRegenRef = useCallback(
    async (payload: ImageGenSubmit, target: { filename: string; type: string }) => {
      const body: Record<string, unknown> = {
        prompt_type: target.type,
        prompt: payload.prompt,
        reference_image: target.filename,
      }
      if (payload.backend) body.backend = payload.backend
      if (payload.loras) body.loras = payload.loras
      if (payload.prompt_settings_applied) body.settings_applied = true
      // Regenerate with the existing image as its own reference.
      if (payload.use_source_as_reference) body.use_source_as_reference = true
      // Checkbox off: replace the existing image in place instead of creating a new one.
      if (payload.create_new === false) body.replace_source = true
      // Optional "what do you want to change" request → the server rewrites the prompt
      // via LLM (same enhance_prompt function as Character/Instagram).
      if (payload.improvement_request) body.improvement_request = payload.improvement_request
      void apiPost(`/world/locations/${encodeURIComponent(locationId)}/gallery`, body)
        .then(() => toast(t('Image queued')))
        .catch((e) => { toast(t('Error') + ': ' + (e as Error).message, 'error') })
    },
    [locationId, t, toast],
  )

  // Multi-select delete: toggle mode, collect filenames, delete sequentially.
  const [selectMode, setSelectMode] = useState(false)
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [confirmBulk, setConfirmBulk] = useState(false)
  const toggleSelect = useCallback((image: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(image)) next.delete(image); else next.add(image)
      return next
    })
  }, [])
  const exitSelect = useCallback(() => {
    setSelectMode(false); setSelected(new Set()); setConfirmBulk(false)
  }, [])
  const removeSelected = useCallback(async () => {
    const names = Array.from(selected)
    if (!names.length) return
    setBusy('__bulk__')
    let ok = 0
    for (const image of names) {
      try {
        await apiDelete(
          `/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(image)}`,
        )
        ok++
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      }
    }
    toast(t('{n} images deleted').replace('{n}', String(ok)))
    setBusy(null)
    exitSelect()
    await reload()
  }, [selected, locationId, exitSelect, reload, t, toast])

  // Two-step delete (no window.confirm — in-app confirmation): the first
  // click arms the tile ("Sure?"), the second deletes; arming a different
  // tile moves the armed state there.
  const [armedRemove, setArmedRemove] = useState<string | null>(null)
  const remove = useCallback(
    async (image: string) => {
      if (armedRemove !== image) {
        setArmedRemove(image)
        return
      }
      setArmedRemove(null)
      setBusy(image)
      try {
        await apiDelete(
          `/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(image)}`,
        )
        await reload()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      } finally {
        setBusy(null)
      }
    },
    [armedRemove, locationId, reload, t, toast],
  )

  // Upload a background image for this location (optionally a room, when roomFilter
  // is set) instead of generating one.
  const uploadRef = useRef<HTMLInputElement>(null)
  const uploadBg = useCallback(async (file: File) => {
    if (!file) return
    setBusy('upload')
    try {
      const fd = new FormData()
      fd.append('file', file)
      if (roomFilter) fd.append('room_id', roomFilter)
      await fetch(`/world/locations/${encodeURIComponent(locationId)}/background/upload`, {
        method: 'POST', body: fd, credentials: 'same-origin',
      })
      await reload()
      toast(t('Saved'))
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    } finally {
      setBusy(null)
    }
  }, [locationId, roomFilter, reload, t, toast])

  // Stable handler for opening the "move image" flow (keeps GalleryCard memoized).
  const startMove = useCallback((image: string) => {
    setMoveImage(image)
    setMoveTarget('')
  }, [])

  const generatePanel = (
    <div className="ga-gallery-generate">
      {imageSetOpen ? (
        <ImageSetDialog location={location} onClose={() => setImageSetOpen(false)} />
      ) : null}
      {mode === '2d' ? (
        <>
          <button
            className="ga-btn ga-btn-sm"
            disabled={!!busy}
            onClick={() => setDialogType('day')}
            title={t('Open the image generation dialog with the day prompt.')}
          >
            ☀️ {t('Generate day')}
          </button>
          <button
            className="ga-btn ga-btn-sm"
            disabled={!!busy}
            onClick={() => setDialogType('night')}
            title={t('Open the image generation dialog with the night prompt.')}
          >
            🌙 {t('Generate night')}
          </button>
          {!roomFilter ? (
            <button
              className="ga-btn ga-btn-sm"
              disabled={!!busy}
              onClick={() => setDialogType('map_2d')}
              title={t('Open the image generation dialog for the flat 2D map icon.')}
            >
              🟦 {t('Generate 2D icon')}
            </button>
          ) : null}
          {!roomFilter ? (
            <button
              className="ga-btn ga-btn-sm"
              disabled={!!busy}
              onClick={() => setDialogType('map_3x3')}
              title={t('Generate a seamless ground image spanning 3×3 map cells — placed per cell in the map editor.')}
            >
              🟩 {t('Generate 3×3 tile')}
            </button>
          ) : null}
          {roomFilter ? (
            <button
              className="ga-btn ga-btn-sm"
              disabled={!!busy}
              onClick={() => setDialogType('building')}
              title={t('Generate the room’s model source image (open-top interior — feeds the 3D room model via 🧊).')}
            >
              🏛 {t('Generate model image')}
            </button>
          ) : null}
          {!roomFilter ? (
            <button
              className="ga-btn ga-btn-sm"
              disabled={!!busy}
              onClick={() => setImageSetOpen(true)}
              title={t('Generate a full image set (location and/or all rooms, day + night) with one chosen backend/model — runs as sequential background jobs.')}
            >
              🖼 {t('Image set…')}
            </button>
          ) : null}
        </>
      ) : (
        <button
          className="ga-btn ga-btn-sm"
          disabled={!!busy}
          onClick={() => setDialogType('building')}
          title={t('Open the image generation dialog for the building exterior (source of the 3D building model).')}
        >
          🏛 {t('Generate building')}
        </button>
      )}
      {!selectMode ? (
        <button
          className="ga-btn ga-btn-sm"
          disabled={!!busy}
          onClick={() => setSelectMode(true)}
          title={t('Select multiple images to delete them at once.')}
        >
          ☑ {t('Select')}
        </button>
      ) : (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
          {confirmBulk ? (
            <>
              <span style={{ fontSize: '0.82em', color: '#e0a356' }}>
                {t('Delete {n} images? Irreversible.').replace('{n}', String(selected.size))}
              </span>
              <button className="ga-btn ga-btn-sm ga-btn-danger" disabled={!!busy}
                onClick={() => { void removeSelected() }}>
                {busy === '__bulk__' ? t('Deleting…') : t('Delete')}
              </button>
            </>
          ) : (
            <button className="ga-btn ga-btn-sm ga-btn-danger"
              disabled={!!busy || selected.size === 0}
              onClick={() => setConfirmBulk(true)}>
              🗑 {t('Delete selected ({n})').replace('{n}', String(selected.size))}
            </button>
          )}
          <button className="ga-btn ga-btn-sm" disabled={busy === '__bulk__'} onClick={exitSelect}>
            {t('Cancel')}
          </button>
        </span>
      )}
      {mode === '2d' ? (
        <>
          <button
            className="ga-btn ga-btn-sm"
            disabled={!!busy}
            onClick={() => uploadRef.current?.click()}
            title={roomFilter ? t('Upload a background image for this room.') : t('Upload a background image for this place.')}
          >
            ⬆ {t('Upload')}
          </button>
          <input
            ref={uploadRef}
            type="file"
            accept="image/*"
            style={{ display: 'none' }}
            onChange={(e) => { const f = e.target.files?.[0]; if (f) void uploadBg(f); e.target.value = '' }}
          />
        </>
      ) : null}
      <button
        className="ga-btn ga-btn-sm"
        disabled={!!busy}
        onClick={() => { void reload() }}
        title={t('Reload the gallery (show newly generated images)')}
      >
        🔄 {t('Refresh')}
      </button>
    </div>
  )

  // EVERY render type composes on the SERVER — one composer for dialog and
  // batch, and it alone decides the use case (room vs. location, indoor vs.
  // outdoor, map vs. background). The client neither knows the style nor the
  // subject chain anymore; it shows the finished prompt and lets it be edited.
  const composeRequest = useMemo(
    () => (dialogType
      ? {
          location_id: locationId,
          // Map tiles belong to the location, never to a room.
          room_id: (roomFilter && dialogType !== 'map_2d' && dialogType !== 'map_3x3')
            ? roomFilter : '',
          prompt_type: dialogType,
        }
      : undefined),
    [dialogType, locationId, roomFilter],
  )
  // Same for the regenerate dialog — but its prompt is a literal adjustment
  // order, so it asks for the bare SUBJECT (no style, no hint, no guard).
  const regenRequest = useMemo(
    () => (regenTarget
      ? {
          location_id: locationId,
          room_id: (roomFilter && regenTarget.type !== 'map_2d'
                    && regenTarget.type !== 'map_3x3') ? roomFilter : '',
          prompt_type: regenTarget.type,
          subject_only: true,
        }
      : undefined),
    [regenTarget, locationId, roomFilter],
  )

  const dialog = dialogType ? (
    <ImageGenDialog
      open
      title={
        dialogType === 'day'
          ? t('Generate day image — {name}').replace('{name}', room?.name || location.name)
          : dialogType === 'night'
            ? t('Generate night image — {name}').replace('{name}', room?.name || location.name)
            : dialogType === 'building'
              ? t('Generate building image — {name}').replace('{name}', room?.name || location.name)
              : dialogType === 'map_3x3'
                ? t('Generate 3×3 map tile — {name}').replace('{name}', location.name)
                : t('Generate 2D map icon — {name}').replace('{name}', location.name)
      }
      defaultPrompt=""
      composeRequest={composeRequest}
      // The composed negative is editable and goes back with the submit — it
      // carries what the negation guard moved out of the subject.
      //
      // Map tiles stay square by contract (they have to tile) — no size fields
      // there. Everything else may pick its own; only the room-model source
      // arrives prefilled from the floor plan.
      showResolution={dialogType === 'day' || dialogType === 'night' || dialogType === 'building'}
      defaultResolution={dialogType === 'building' ? roomResolution : null}
      onSubmit={submitGenerate}
      onClose={() => setDialogType(null)}
    />
  ) : null

  const regenDialog = regenTarget ? (
    <ImageGenDialog
      open
      title={t('Adjust image — {name}').replace('{name}', room?.name || location.name)}
      mode="regenerate"
      defaultPrompt=""
      composeRequest={regenRequest}
      hideNegative
      sourceImageUrl={`/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(regenTarget.filename)}`}
      defaultUseSource
      requireSourceReference
      defaultCreateNew
      onSubmit={(payload) => submitRegenRef(payload, regenTarget)}
      onClose={() => setRegenTarget(null)}
    />
  ) : null

  if (!data) return <div className="ga-loading">{t('Loading…')}</div>
  if (!images.length) {
    return (
      <>
        {generatePanel}
        {dialog}
        {regenDialog}
        <div className="ga-form-hint" style={{ padding: 8 }}>
          {mode === '3d'
            ? t('No building images yet.')
            : roomFilter
              ? t('No gallery images for this room yet.')
              : t('No gallery images yet.')}
        </div>
      </>
    )
  }

  return (
    <>
      {generatePanel}
      {dialog}
      {regenDialog}
      <div className="ga-form-section-label">
        {t('Gallery')} ({images.length})
      </div>
      <div className="ga-gallery-list">
        {images.map((filename) => {
          const meta = metas[filename] || {}
          const type = types[filename] || ''
          const url = `/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(filename)}`
          const isBusy = busy === filename
          return (
            <GalleryCard
              key={filename}
              filename={filename}
              url={url}
              type={type}
              meta={meta}
              isBusy={isBusy}
              mapUsage={mapUsage[filename] || 0}
              selectMode={selectMode}
              isSelected={selected.has(filename)}
              onToggleSelect={toggleSelect}
              onZoom={setZoom}
              onSetType={setType}
              onGenerateNight={generateNight}
              onRegen={setRegenTarget}
              onMove={startMove}
              onRemove={remove}
              removeArmed={armedRemove === filename}
              onGenerateModel={onGenerateModel}
            />
          )
        })}
      </div>

      {zoom ? (
        <div className="ga-gallery-lightbox" onClick={() => setZoom(null)} role="dialog">
          <img src={zoom} alt="" />
          <button
            type="button"
            className="ga-gallery-lightbox-close"
            onClick={() => setZoom(null)}
            aria-label={t('Close')}
          >
            ×
          </button>
        </div>
      ) : null}

      {moveImage ? (
        <div className="ga-modal-backdrop" onMouseDown={() => setMoveImage(null)}>
          <div className="ga-modal" style={{ maxWidth: 460 }} onMouseDown={(e) => e.stopPropagation()}>
            <div className="ga-modal-header">
              <span>{t('Move image to…')}</span>
              <button className="ga-modal-close" onClick={() => setMoveImage(null)}>×</button>
            </div>
            <div className="ga-modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              <img
                src={`/world/locations/${encodeURIComponent(locationId)}/gallery/${encodeURIComponent(moveImage)}`}
                alt=""
                style={{ display: 'block', width: '100%', maxHeight: 220, objectFit: 'contain', borderRadius: 6, background: 'var(--bg, #0d1117)' }}
              />
              <label style={{ fontSize: '0.85em' }}>
                {t('Target location')}
                <select
                  className="ga-input"
                  value={moveTarget}
                  onChange={(e) => setMoveTarget(e.target.value)}
                  style={{ width: '100%', marginTop: 4 }}
                >
                  <option value="">— {t('select')} —</option>
                  {allLocations.filter((l) => l.id !== locationId).map((l) => (
                    <option key={l.id} value={l.id}>{l.name}</option>
                  ))}
                </select>
              </label>
            </div>
            <div className="ga-modal-footer" style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
              <button className="ga-btn" onClick={() => setMoveImage(null)}>{t('Cancel')}</button>
              <button className="ga-btn ga-btn-primary" disabled={!moveTarget} onClick={submitMove}>
                {t('Move')}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  )
}
